// The behavior of 'auto' can be mapped to template type deduction.

// Consider this 'auto' declaration:
int i = 42;
auto x = i;          // Case 3: auto behaves like T
const auto& rx = i;  // Case 1: auto behaves like const T&
auto&& urx = 27;     // Case 2: auto behaves like T&&

// Conceptually, the compiler acts as if it's deducing T for these templates:
template<typename T> void func_case3(T param);       // for auto x
template<typename T> void func_case1(const T& param); // for const auto& rx
template<typename T> void func_case2(T&& param);      // for auto&& urx

// func_case3(i);  // T would be deduced as int, so x is int
// func_case1(i);  // T would be deduced as int, so rx is const int&
// func_case2(27); // T would be deduced as int, so urx is int&&
